_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0131000" if __import__("os").path.isdir("./environment_mix/0131000") else "/app/database")
def met_museum_search_museum_objects(q, hasImages=False, title=False, departmentId=None):
    import json, os
    db = json.load(open(os.path.join(_DB, 'met.json'), encoding='utf-8'))
    ql = (q or '').lower()
    ids = []
    for oid, o in db['objects'].items():
        hay = (o['title'] + ' ' + o['artistDisplayName']).lower()
        if ql and ql not in hay:
            continue
        if hasImages and not o.get('primaryImage'):
            continue
        if departmentId is not None and o.get('departmentId') != departmentId:
            continue
        ids.append(o['objectID'])
    return {'total': len(ids), 'objectIDs': ids}

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0131000" if __import__("os").path.isdir("./environment_mix/0131000") else "/app/database")
def met_museum_get_museum_object(objectId, returnImage=True):
    import json, os
    db = json.load(open(os.path.join(_DB, 'met.json'), encoding='utf-8'))
    o = db['objects'].get(str(objectId))
    if not o:
        return {'error': 'object ' + str(objectId) + ' not found'}
    o = dict(o)
    if not returnImage:
        o.pop('primaryImage', None)
    return o
